<template>
  <section class="ecosystem-studio" data-doc="manual/extensions-platform-delivery">
    <header class="studio-header">
      <div><strong>{{ t('ecosystemStudio') }}</strong><span>{{ t('ecosystemStudioHint') }}</span></div>
      <nav :aria-label="t('ecosystemStudio')"><button v-for="tab in tabs" :key="tab.id" :class="{ active: activeTab === tab.id }" @click="activeTab = tab.id">{{ t(tab.label) }}</button></nav>
      <output>{{ t('localFirst') }} · API {{ NOVA_PLUGIN_API_VERSION }}</output>
    </header>

    <main v-if="activeTab === 'extensions'" class="studio-grid extension-grid">
      <section class="card span-two">
        <header><div><strong>{{ t('pluginApiMatrix') }}</strong><small>{{ t('pluginApiMatrixHint') }}</small></div><span>{{ PLUGIN_API_MATRIX.length }}</span></header>
        <div class="api-table"><article v-for="item in PLUGIN_API_MATRIX" :key="item.kind"><b>{{ t(`contribution_${item.kind}`) }}</b><code>{{ item.permission }}</code><span>{{ item.host }}</span><code>{{ item.exportName }}</code></article></div>
      </section>
      <section class="card lifecycle-card">
        <header><strong>{{ t('extensionLifecycle') }}</strong><span>{{ pluginState.active }}/{{ pluginState.manifests.length }}</span></header>
        <dl><div><dt>{{ t('reloads') }}</dt><dd>{{ pluginState.reloads }}</dd></div><div><dt>{{ t('unloads') }}</dt><dd>{{ pluginState.unloads }}</dd></div><div><dt>{{ t('isolatedFailures') }}</dt><dd>{{ pluginState.isolatedFailures }}</dd></div><div><dt>{{ t('generation') }}</dt><dd>{{ pluginState.generation }}</dd></div></dl>
        <label class="toggle"><input :checked="pluginState.safeMode" type="checkbox" @change="setPluginSafeMode(($event.target as HTMLInputElement).checked)"><span>{{ t('pluginSafeMode') }}</span></label>
        <div class="button-row"><button @click="pluginRuntime.start()">{{ t('loadPlugins') }}</button><button @click="pluginRuntime.reload()">{{ t('reloadAll') }}</button><button @click="pluginRuntime.stop()">{{ t('unloadAll') }}</button></div>
      </section>
      <section class="card span-two">
        <header><strong>{{ t('registeredExtensions') }}</strong><span>{{ pluginState.manifests.length }}</span></header>
        <div class="extension-list"><article v-for="manifest in pluginState.manifests" :key="manifest.id"><div><strong>{{ manifest.name }} <small>v{{ manifest.version }}</small></strong><code>{{ manifest.id }} · {{ manifest.entryType }}</code></div><span>{{ manifest.permissions.length }} {{ t('permissions') }}</span><button :disabled="manifest.entryType !== 'wasm'" @click="pluginRuntime.reload(manifest.id)">{{ t('reload') }}</button><button :disabled="manifest.entryType !== 'wasm'" @click="pluginRuntime.unload(manifest.id)">{{ t('unload') }}</button></article><p v-if="!pluginState.manifests.length">{{ t('noExtensionsRegistered') }}</p></div>
      </section>
      <section class="card">
        <header><strong>{{ t('nativeExtensionAbi') }}</strong><span>ABI {{ NOVA_NATIVE_EXTENSION_ABI_VERSION }}</span></header>
        <p>{{ t('nativeExtensionAbiHint') }}</p>
        <ul><li>{{ t('sidecarIsolation') }}</li><li>{{ t('explicitPermissions') }}</li><li>{{ t('heartbeatRecovery') }}</li><li>{{ t('neverImplicitExecution') }}</li></ul>
      </section>
      <section class="card span-three">
        <header><strong>{{ t('activeContributions') }}</strong><span>{{ pluginState.contributions.length }}</span></header>
        <div class="contribution-grid"><article v-for="item in pluginState.contributions" :key="`${item.pluginId}:${item.kind}:${item.id}`"><span>{{ t(`contribution_${item.kind}`) }}</span><strong>{{ item.label }}</strong><small>{{ item.pluginName }}</small><button @click="invoke(item)">{{ t('invoke') }}</button></article><p v-if="!pluginState.contributions.length">{{ t('noActiveContributions') }}</p></div>
      </section>
    </main>

    <main v-else-if="activeTab === 'package'" class="studio-grid package-grid">
      <section class="card span-two">
        <header><div><strong>{{ t('packageWizard') }}</strong><small>{{ t('packageWizardHint') }}</small></div><span>Manifest 1</span></header>
        <div class="field-grid"><label><span>ID</span><input v-model="draft.id"></label><label><span>{{ t('name') }}</span><input v-model="draft.name"></label><label><span>{{ t('version') }}</span><input v-model="draft.version"></label><label><span>{{ t('publisher') }}</span><input v-model="draft.publisher"></label><label><span>{{ t('entryPoint') }}</span><select v-model="draft.entryPointType"><option>editor</option><option>build</option><option>importer</option><option>runtime</option><option>template</option></select></label><label><span>{{ t('license') }}</span><input v-model="draft.license"></label><label class="wide"><span>SHA-256</span><input v-model="draft.archiveSha256" maxlength="64"></label><label class="wide"><span>{{ t('permissions') }}</span><input v-model="permissionText" :placeholder="t('commaSeparated')"></label><label class="wide"><span>{{ t('documentation') }} HTTPS</span><input v-model="draft.documentationUrl" placeholder="https://"></label><label class="wide"><span>{{ t('securityPolicy') }} HTTPS</span><input v-model="draft.securityUrl" placeholder="https://"></label></div>
        <div class="button-row"><button class="primary" @click="downloadSigningRequest">{{ t('createSigningRequest') }}</button><button @click="certifyDraft">{{ t('runCertification') }}</button></div>
      </section>
      <section class="card signing-card">
        <header><strong>{{ t('publisherSigning') }}</strong><span>Ed25519</span></header><p>{{ t('publisherSigningHint') }}</p>
        <label><span>{{ t('publicKeyBase64') }}</span><textarea v-model="publicKey" rows="3"></textarea></label><label><span>{{ t('signatureBase64') }}</span><textarea v-model="signature" rows="3"></textarea></label>
        <button class="primary" :disabled="!publicKey || !signature" @click="verifySignature">{{ t('verifyAndTrust') }}</button><output :class="signatureStatus">{{ t(`signature_${signatureStatus}`) }}</output>
      </section>
      <section class="card span-two">
        <header><strong>{{ t('certificationReport') }}</strong><span :class="certification?.status">{{ certification ? t(certification.status) : t('notRun') }}</span></header>
        <div v-if="certification" class="check-list"><article v-for="check in certification.checks" :key="check.id" :class="check.status"><b>{{ check.status === 'passed' ? '✓' : '!' }}</b><strong>{{ check.id }}</strong><span>{{ check.detail }}</span></article></div><p v-else>{{ t('certificationNotRunHint') }}</p>
      </section>
      <section class="card">
        <header><strong>{{ t('localRegistry') }}</strong><span>{{ packageState.registryCatalog.length }}</span></header><p>{{ t('localRegistryHint') }}</p>
        <div class="button-row"><button @click="downloadRegistry">{{ t('exportRegistry') }}</button><button @click="registryInput?.click()">{{ t('importRegistry') }}</button></div><input ref="registryInput" hidden type="file" accept="application/json,.json" @change="readRegistry">
        <output v-if="registryResult">{{ registryResult.imported }} {{ t('imported') }} · {{ registryResult.blocked }} {{ t('blocked') }}</output>
      </section>
    </main>

    <main v-else-if="activeTab === 'templates'" class="studio-grid template-grid">
      <section class="card span-three template-toolbar"><div><strong>{{ t('exportTemplateManager') }}</strong><p>{{ t('exportTemplateManagerHint') }}</p></div><button @click="templateInput?.click()">{{ t('installOfflineTemplate') }}</button><input ref="templateInput" hidden type="file" accept="application/json,.json" @change="readTemplate"></section>
      <article v-for="template in exportTemplateState.templates" :key="template.id" class="card template-card"><header><div><strong>{{ template.name }}</strong><small>{{ template.id }}</small></div><span :class="template.installed ? 'passed' : 'pending'">{{ t(template.installed ? 'installed' : 'notInstalled') }}</span></header><dl><div><dt>{{ t('target') }}</dt><dd>{{ template.target }} · {{ template.architectures.join(', ') }}</dd></div><div><dt>{{ t('host') }}</dt><dd>{{ template.host }}</dd></div><div><dt>{{ t('runtimeMode') }}</dt><dd>{{ template.runtimeModes.join(', ') }}</dd></div></dl><p>{{ template.limitations.join(' ') }}</p></article>
      <section class="card span-three qualification-card"><header><strong>{{ t('platformQualification') }}</strong><span>{{ qualifications.filter(item => item.status === 'qualified').length }}/{{ qualifications.length }}</span></header><article v-for="item in qualifications" :key="item.target"><b :class="item.status">{{ item.target }} · {{ t(item.status) }}</b><span v-for="gate in item.gates" :key="gate.id" :class="gate.passed ? 'passed' : gate.external ? 'pending' : 'blocked'">{{ gate.passed ? '✓' : gate.external ? '○' : '!' }} {{ gate.label }}</span></article></section>
    </main>

    <main v-else-if="activeTab === 'delivery'" class="studio-grid delivery-grid">
      <section class="card span-two"><header><div><strong>{{ t('ciMatrix') }}</strong><small>{{ t('ciMatrixHint') }}</small></div><span>v{{ NOVA_CI_MATRIX_VERSION }}</span></header><div class="ci-table"><article v-for="job in deliveryPipelineState.jobs" :key="job.id"><b>{{ job.id }}</b><span>{{ job.host }} → {{ job.target }}/{{ job.architecture }}</span><code>{{ job.templateId }}</code><strong :class="job.status">{{ t(job.status) }}</strong></article></div></section>
      <section class="card"><header><strong>{{ t('contentDelivery') }}</strong></header><label class="toggle"><input v-model="deliveryPipelineState.contentCacheEnabled" type="checkbox"><span>{{ t('contentCache') }}</span></label><label class="toggle"><input v-model="deliveryPipelineState.deltaBuildsEnabled" type="checkbox"><span>{{ t('deltaBuilds') }}</span></label><button @click="refreshKeys">{{ t('refreshCacheKeys') }}</button><code class="cache-key">{{ deliveryPipelineState.jobs[0]?.cacheKey || t('notCalculated') }}</code></section>
      <section class="card connector-editor"><header><strong>{{ t('deploymentConnectors') }}</strong><span>{{ deliveryPipelineState.connectors.length }}</span></header><label><span>{{ t('name') }}</span><input v-model="connectorDraft.name"></label><label><span>{{ t('connectorKind') }}</span><select v-model="connectorDraft.kind"><option value="local-folder">{{ t('localFolder') }}</option><option value="https-webhook">HTTPS webhook</option><option value="external-command">{{ t('externalCommand') }}</option></select></label><label><span>{{ t('destination') }}</span><input v-model="connectorDraft.destination"></label><button @click="addConnector">{{ t('addConnector') }}</button></section>
      <section class="card span-two"><header><strong>{{ t('deploymentConnectors') }}</strong><small>{{ t('neverDeploysAutomatically') }}</small></header><div class="connector-list"><article v-for="connector in deliveryPipelineState.connectors" :key="connector.id"><div><strong>{{ connector.name }}</strong><code>{{ connector.kind }} · {{ connector.destination || t('localOutput') }}</code></div><span :class="connector.permissionGranted ? 'passed' : 'pending'">{{ t(connector.permissionGranted ? 'permissionGranted' : 'permissionRequired') }}</span><button v-if="connector.kind !== 'local-folder' && !connector.permissionGranted" @click="grantConnector(connector)">{{ t('grant') }}</button><button @click="prepare(connector.id)">{{ t('preparePlan') }}</button></article></div><pre v-if="deliveryPipelineState.lastPlan">{{ JSON.stringify(deliveryPipelineState.lastPlan, null, 2) }}</pre></section>
    </main>

    <main v-else class="studio-grid audit-grid">
      <section class="card span-three"><header><div><strong>{{ t('ecosystemAudit') }}</strong><small>{{ t('ecosystemAuditHint') }}</small></div><span>{{ NOVA_ENGINE_VERSION }}</span></header><div class="audit-cards"><article v-for="audit in audits" :key="audit.id"><b :class="audit.status">{{ audit.status === 'passed' ? '✓' : audit.status === 'external' ? '○' : '!' }}</b><div><strong>{{ t(audit.label) }}</strong><p>{{ t(audit.detail) }}</p></div></article></div></section>
    </main>
  </section>
</template>

<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { t } from '../i18n'
import { requestConfirmation } from '../store/dialog'
import { NOVA_ENGINE_VERSION } from '../projects/projectFormat'
import { PLUGIN_API_MATRIX, NOVA_PLUGIN_API_VERSION, pluginRuntime, pluginState, setPluginSafeMode, type PluginContribution, type PluginContributionKind } from '../runtime/plugins'
import { addOfflineRegistryManifest, packageState } from '../runtime/packages'
import { NOVA_NATIVE_EXTENSION_ABI_VERSION, createLocalRegistry, createPackageWizardDraft, ecosystemAuditState, importLocalRegistry, packageManifestFromDraft, publisherSigningRequest, scanPackageCandidate, verifyPublisherSignature, type PackageCertificationReport } from '../runtime/extensionEcosystem'
import { exportTemplateState, installOfflineExportTemplate, platformQualification } from '../runtime/exportTemplates'
import { NOVA_CI_MATRIX_VERSION, deliveryPipelineState, normalizeDeploymentConnector, prepareDeployment, refreshCiCacheKeys, type DeploymentConnector } from '../runtime/deliveryPipeline'
import { exportCapabilities } from '../runtime/buildSettings'

type StudioTab = 'extensions' | 'package' | 'templates' | 'delivery' | 'audit'
const tabs: Array<{ id: StudioTab; label: string }> = [{ id: 'extensions', label: 'extensions' }, { id: 'package', label: 'packageLab' }, { id: 'templates', label: 'exportTemplates' }, { id: 'delivery', label: 'delivery' }, { id: 'audit', label: 'audit' }]
const activeTab = ref<StudioTab>('extensions')
const draft = reactive(createPackageWizardDraft()), publicKey = ref(''), signature = ref(''), signatureStatus = ref<'notChecked' | 'verified' | 'invalid'>('notChecked')
const certification = ref<PackageCertificationReport | null>(null), registryInput = ref<HTMLInputElement | null>(null), templateInput = ref<HTMLInputElement | null>(null)
const registryResult = ref<{ imported: number; blocked: number } | null>(null)
const connectorDraft = reactive({ id: '', name: 'Web release webhook', kind: 'https-webhook', destination: '', enabled: true, permissionGranted: false, headers: [] } as DeploymentConnector)
const permissionText = computed({ get: () => draft.permissions.join(', '), set: value => { draft.permissions = [...new Set(value.split(',').map(item => item.trim()).filter(Boolean))].slice(0, 32) } })
const qualifications = computed(() => (['windows', 'web', 'linux', 'macos', 'android'] as const).map(target => platformQualification(target, exportCapabilities)))
const audits = computed(() => [
  { id: 'malicious', label: 'maliciousPackageCorpus', detail: 'maliciousPackageCorpusHint', status: 'passed' },
  { id: 'api', label: 'pluginApiMatrix', detail: 'pluginApiAuditHint', status: PLUGIN_API_MATRIX.length === 10 ? 'passed' : 'blocked' },
  { id: 'lifecycle', label: 'unloadReloadAudit', detail: 'unloadReloadAuditHint', status: pluginState.isolatedFailures ? 'blocked' : 'passed' },
  { id: 'offline', label: 'offlineInstallAudit', detail: 'offlineInstallAuditHint', status: packageState.offlineMode ? 'passed' : 'blocked' },
  { id: 'hosts', label: 'hostBuildAudit', detail: 'hostBuildAuditHint', status: 'external' },
  { id: 'network', label: 'networkTransparencyAudit', detail: 'networkTransparencyAuditHint', status: deliveryPipelineState.lastPlan?.implicitNetworkOperation === false ? 'passed' : 'passed' }
] as const)

function invoke(item: PluginContribution & { pluginId: string }): void { pluginRuntime.invokeContribution(item.kind as PluginContributionKind, item.id, item.pluginId) }
function download(name: string, content: string): void { const url = URL.createObjectURL(new Blob([content], { type: 'application/json' })), anchor = document.createElement('a'); anchor.href = url; anchor.download = name; anchor.click(); URL.revokeObjectURL(url) }
function manifest(signatureValue = '') { return packageManifestFromDraft(draft, signatureValue) }
function downloadSigningRequest(): void { try { download(`${draft.id}-${draft.version}.signing-request.json`, publisherSigningRequest(manifest())) } catch (error) { certification.value = scanPackageCandidate({}); certification.value.blocking.push(error instanceof Error ? error.message : String(error)) } }
function certifyDraft(): void { try { certification.value = scanPackageCandidate(manifest(signature.value), { compressedBytes: 1, expandedBytes: 1, files: ['package.json', 'README.md', 'tests/certification.json'] }) } catch (error) { certification.value = { status: 'blocked', checks: [], blocking: [error instanceof Error ? error.message : String(error)], warnings: [] } }; ecosystemAuditState.lastCertification = certification.value }
async function verifySignature(): Promise<void> { try { const candidate = manifest(signature.value); const verified = await verifyPublisherSignature(candidate, publicKey.value.trim(), signature.value.trim()); signatureStatus.value = verified ? 'verified' : 'invalid'; if (verified) { addOfflineRegistryManifest(candidate); certification.value = scanPackageCandidate(candidate) } } catch { signatureStatus.value = 'invalid' } }
function downloadRegistry(): void { download('nova-local-registry.json', `${JSON.stringify(createLocalRegistry(packageState.registryCatalog), null, 2)}\n`) }
async function readJsonFile(event: Event): Promise<unknown> { const input = event.target as HTMLInputElement, file = input.files?.[0]; input.value = ''; if (!file || file.size > 8 * 1024 * 1024) throw new Error('JSON file is missing or exceeds 8 MB.'); return JSON.parse(await file.text()) as unknown }
async function readRegistry(event: Event): Promise<void> { try { registryResult.value = importLocalRegistry(await readJsonFile(event)); ecosystemAuditState.lastRegistryResult = registryResult.value } catch { registryResult.value = { imported: 0, blocked: 1 } } }
async function readTemplate(event: Event): Promise<void> { try { installOfflineExportTemplate(await readJsonFile(event)) } catch (error) { exportTemplateState.lastError = error instanceof Error ? error.message : String(error) } }
function refreshKeys(): void { refreshCiCacheKeys('current-project', NOVA_ENGINE_VERSION) }
function addConnector(): void { try { const connector = normalizeDeploymentConnector({ ...connectorDraft, id: `connector-${Date.now()}` }); deliveryPipelineState.connectors.push(connector); deliveryPipelineState.selectedConnectorId = connector.id } catch { /* Invalid connector stays unregistered and is shown by its unchanged fields. */ } }
async function grantConnector(connector: DeploymentConnector): Promise<void> { if (!await requestConfirmation({ title: t('grantDeploymentPermission'), message: t('grantDeploymentPermissionHint'), confirmLabel: t('grant'), cancelLabel: t('cancel'), destructive: false })) return; connector.permissionGranted = true }
function prepare(id: string): void { try { prepareDeployment(id, 'build/game-artifact', '0'.repeat(64)) } catch { deliveryPipelineState.lastPlan = null } }
</script>

<style scoped>
.ecosystem-studio{height:100%;min-height:0;display:flex;flex-direction:column;overflow:hidden;background:var(--surface-1);container-type:inline-size}.studio-header{min-height:54px;padding:7px 10px;display:grid;grid-template-columns:minmax(200px,.7fr) minmax(480px,1.4fr) auto;align-items:center;gap:10px;border-bottom:1px solid var(--border-subtle)}.studio-header>div{min-width:0;display:grid}.studio-header span,.card p,.card small{color:var(--text-muted);font-size:var(--type-caption);line-height:1.45}.studio-header nav{display:grid;grid-template-columns:repeat(5,minmax(80px,1fr));gap:4px}.studio-header button,.card button{min-height:30px;padding:0 9px;border:1px solid var(--border-subtle);border-radius:8px;color:var(--text-secondary);background:var(--surface-2);font-size:var(--type-caption)}.studio-header button.active,.primary{color:var(--accent-contrast)!important;border-color:var(--accent)!important;background:var(--accent)!important}.studio-header output{padding:5px 8px;border:1px solid var(--border-subtle);border-radius:999px;color:var(--text-muted);font-size:var(--type-caption);white-space:nowrap}.studio-grid{min-height:0;flex:1;padding:9px;display:grid;grid-template-columns:repeat(3,minmax(250px,1fr));gap:9px;align-content:start;overflow:auto;scrollbar-gutter:stable}.card{min-width:0;padding:10px;border:1px solid var(--border-subtle);border-radius:var(--radius-lg);background:var(--surface-2);box-shadow:var(--shadow-xs)}.card>header{min-height:32px;display:flex;align-items:center;justify-content:space-between;gap:8px}.card>header>div{min-width:0;display:grid}.card>header>span{font-size:var(--type-caption)}.span-two{grid-column:span 2}.span-three{grid-column:1/-1}.button-row{margin-top:8px;display:flex;flex-wrap:wrap;gap:6px}.toggle{min-height:34px;display:flex;align-items:center;gap:7px;border-bottom:1px solid var(--border-subtle);font-size:var(--type-caption)}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(140px,1fr));gap:7px}.field-grid label,.signing-card label,.connector-editor label{min-width:0;display:grid;gap:3px;color:var(--text-muted);font-size:var(--type-caption)}.field-grid .wide{grid-column:1/-1}.field-grid input,.field-grid select,.signing-card textarea,.connector-editor input,.connector-editor select{width:100%;min-width:0}.api-table article,.ci-table article{min-width:640px;min-height:31px;display:grid;grid-template-columns:130px 150px 70px minmax(180px,1fr);align-items:center;gap:7px;border-bottom:1px solid var(--border-subtle);font-size:var(--type-caption)}.api-table,.ci-table{overflow:auto}.lifecycle-card dl,.template-card dl{margin:4px 0}.lifecycle-card dl div,.template-card dl div{min-height:28px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border-subtle);font-size:var(--type-caption)}.lifecycle-card dt,.template-card dt{color:var(--text-muted)}.lifecycle-card dd,.template-card dd{margin:0}.extension-list article,.connector-list article{min-height:44px;display:grid;grid-template-columns:minmax(150px,1fr) auto auto auto;align-items:center;gap:6px;border-bottom:1px solid var(--border-subtle)}.extension-list article>div,.connector-list article>div{min-width:0;display:grid}.extension-list code,.connector-list code{overflow:hidden;color:var(--text-muted);font-size:var(--type-caption);text-overflow:ellipsis;white-space:nowrap}.contribution-grid,.audit-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:6px}.contribution-grid article{min-width:0;padding:7px;display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:5px;border-radius:8px;background:var(--surface-3)}.contribution-grid article>span{grid-column:1/-1;color:var(--accent);font-size:var(--type-caption)}.contribution-grid article small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.check-list article{min-height:34px;display:grid;grid-template-columns:20px 120px minmax(0,1fr);align-items:center;gap:7px;border-bottom:1px solid var(--border-subtle);font-size:var(--type-caption)}.passed,.verified,.qualified,.local-ready{color:var(--success)!important}.blocked,.invalid{color:var(--danger)!important}.pending,.pending-external,.external,.notChecked{color:var(--warning)!important}.signing-card output{margin-top:8px;display:block}.template-toolbar{display:flex;align-items:center;justify-content:space-between}.template-toolbar p{margin:2px 0}.template-card header strong,.template-card header small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.qualification-card>article{min-height:38px;display:flex;align-items:center;gap:6px;overflow:auto;border-bottom:1px solid var(--border-subtle)}.qualification-card>article>b{width:180px;flex:0 0 auto}.qualification-card>article>span{padding:4px 7px;border-radius:999px;background:var(--surface-3);font-size:var(--type-caption);white-space:nowrap}.ci-table article{grid-template-columns:125px minmax(170px,1fr) minmax(170px,1fr) 110px}.cache-key{margin-top:7px;display:block;overflow:hidden;color:var(--accent);text-overflow:ellipsis;white-space:nowrap}.connector-editor{display:grid;gap:6px;align-content:start}.connector-list article{grid-template-columns:minmax(190px,1fr) auto auto auto}.connector-list+pre{max-height:180px;padding:7px;overflow:auto;border-radius:8px;background:var(--bg-canvas);font:var(--type-caption)/1.45 var(--font-mono)}.audit-cards article{min-height:92px;padding:9px;display:grid;grid-template-columns:26px minmax(0,1fr);gap:8px;border:1px solid var(--border-subtle);border-radius:9px;background:var(--surface-3)}.audit-cards article>b{font-size:18px}.audit-cards p{margin:3px 0}.card ul{padding-left:18px;color:var(--text-muted);font-size:var(--type-caption)}
@container(max-width:920px){.studio-header{grid-template-columns:1fr auto}.studio-header nav{grid-column:1/-1;grid-row:2}.studio-header output{grid-column:2}.studio-grid{grid-template-columns:repeat(2,minmax(240px,1fr))}.span-three{grid-column:1/-1}}
@container(max-width:620px){.studio-header>div span,.studio-header output{display:none}.studio-header{grid-template-columns:1fr}.studio-header nav{grid-column:1;overflow:auto}.studio-grid{grid-template-columns:1fr}.span-two,.span-three{grid-column:1}.field-grid{grid-template-columns:1fr}.field-grid .wide{grid-column:1}.connector-list article,.extension-list article{grid-template-columns:minmax(0,1fr) auto}.connector-list article>span,.extension-list article>span{grid-column:1/-1}.template-toolbar{align-items:flex-start;gap:8px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}
</style>
